import 'dart:io';\nimport 'package:path/path.dart' as path;\n\n/// Handles export of tabular data to CSV format.\nclass CsvExporter {\n  /// Exports a list of maps (representing rows) to a CSV file.\n  /// Headers are derived from the keys of the first map.\n  Future<void> exportToCsv(List<Map<String, dynamic>> data, String filePath) async {\n    if (data.isEmpty) {\n      print('Data is empty. Nothing to export.');\n      return;\n    }\n\n    try {\n      final file = File(filePath);\n      await file.parent.create(recursive: true);\n      \n      final buffer = StringBuffer();\n      \n      // Extract headers from the first row\n      final headers = data.first.keys.toList();\n      buffer.writeln(headers.join(','));\n      \n      // Write data rows\n      for (final row in data) {\n        final csvRow = headers.map((header) {\n          var value = row[header]?.toString() ?? '';\n          // Escape values that contain commas, quotes, or newlines\n          if (value.contains(',') || value.contains('\"') || value.contains('\\n')) {\n            value = '\"\\${value.replaceAll('\"', '\"\"')}\"';\n          }\n          return value;\n        }).join(',');\n        buffer.writeln(csvRow);\n      }\n\n      await file.writeAsString(buffer.toString());\n      print('CSV Exported to: \\${path.basename(filePath)}');\n    } catch (e) {\n      print('CSV Export Error: \\$(e.toString())');\n    }\n  }\n}\n
